@extends('layouts.app') @section('title',$product->exists?'Ubah Barang':'Tambah Barang') @section('heading',$product->exists?'Ubah Master Barang':'Tambah Master Barang') @section('content')<form method="POST" action="{{ $product->exists ? route('products.update',$product) : route('products.store') }}" class="card max-w-5xl">@csrf @if($product->exists)@method('PUT')@endif<div class="mb-5 rounded-xl bg-emerald-50 p-4 text-sm text-emerald-800">Lengkapi identitas barang, pemasok, harga, satuan, dan stok.</div><div class="grid gap-5 md:grid-cols-2"><div><label class="label">Nama barang *</label><input class="input" name="name" value="{{ old('name',$product->name) }}" required></div><div><label class="label">Kode barang *</label><input class="input" name="code" value="{{ old('code',$product->code) }}" required></div><div><label class="label">Barcode</label><input class="input" name="barcode" value="{{ old('barcode',$product->barcode) }}" placeholder="Scan atau ketik barcode"></div><div><label class="label">Kategori</label><select class="input" name="category_id"><option value="">Pilih kategori</option>@foreach($categories as $row)<option value="{{ $row->id }}" @selected(old('category_id',$product->category_id)==$row->id)>{{ $row->name }}</option>@endforeach</select></div><div><label class="label">Merek</label><select class="input" name="brand_id"><option value="">Pilih merek</option>@foreach($brands as $row)<option value="{{ $row->id }}" @selected(old('brand_id',$product->brand_id)==$row->id)>{{ $row->name }}</option>@endforeach</select></div><div><label class="label">Supplier utama</label><select class="input" name="supplier_id"><option value="">Pilih supplier</option>@foreach($suppliers as $row)<option value="{{ $row->id }}" @selected(old('supplier_id',$product->supplier_id)==$row->id)>{{ $row->name }}</option>@endforeach</select></div><div><label class="label">Satuan master</label><select class="input" id="unit_id" name="unit_id"><option value="">Pilih satuan</option>@foreach($units as $row)<option value="{{ $row->id }}" data-name="{{ $row->name }}" @selected(old('unit_id',$product->unit_id)==$row->id)>{{ $row->name }}{{ $row->symbol ? ' ('.$row->symbol.')' : '' }}</option>@endforeach</select><input type="hidden" id="unit" name="unit" value="{{ old('unit',$product->unit ?: 'pcs') }}"></div><div><label class="label">Harga beli *</label><input class="input" name="buy_price" type="number" min="0" value="{{ old('buy_price',$product->buy_price ?? 0) }}" required></div><div><label class="label">Harga jual *</label><input class="input" name="price" type="number" min="0" value="{{ old('price',$product->price) }}" required></div><div><label class="label">Stok awal *</label><input class="input" name="stock" type="number" min="0" value="{{ old('stock',$product->stock ?? 0) }}" required></div><div><label class="label">Minimum stok *</label><input class="input" name="minimum_stock" type="number" min="0" value="{{ old('minimum_stock',$product->minimum_stock ?? 5) }}" required></div><div><label class="label">Status</label><label class="mt-3 flex items-center gap-2 text-sm font-semibold"><input name="is_active" type="checkbox" value="1" @checked(old('is_active',$product->exists ? $product->is_active : true))> Barang aktif dan tampil di kasir</label></div><div class="md:col-span-2"><label class="label">Keterangan</label><textarea class="input" name="description" rows="3">{{ old('description',$product->description) }}</textarea></div></div><div class="mt-6 flex gap-3"><button class="btn-primary">Simpan Master Barang</button><a class="btn-muted" href="{{ route('products.index') }}">Batal</a></div></form><script>document.querySelector('#unit_id').addEventListener('change',e=>{let o=e.target.selectedOptions[0];if(o.dataset.name)document.querySelector('#unit').value=o.dataset.name});</script>@endsection
